var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test case: integer without decimal part should still be valid
    assert.strictEqual(bytes.parse('1000kb'), 1024000);
    // The original regex allowed integers (\d+) but the new one requires \d(?:\.\d+)?
    // This means '1000' as a standalone number (without unit) would fail to parse
    // But the original regex would have matched '1000' as valid when followed by unit
    // However, the issue is more subtle: '1000kb' should parse, but now it might not
    // Because the regex is now ^((-|+)?(\d(?:\.\d+)?)) *(kb|mb|gb|tb|pb)$
    // This allows '1000' as the number part, but the original was \d+(?:\.\d+)?
    // The difference is that \d+(?:\.\d+)? allows one or more digits
    // The new \d(?:\.\d+)? allows exactly one digit, then an optional decimal part
    // So '1000kb' should still match because '1000' is multiple digits
    // But wait: \d(?:\.\d+)? is just one digit followed by optional decimal
    // So '1000' does NOT match \d(?:\.\d+)? because it has 4 digits
    // Therefore '1000kb' would fail to parse
    assert.strictEqual(bytes.parse('1000kb'), 1024000, '1000kb should parse to 1024000');
  });
});

