var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test case where the decimal part has a digit after a non-zero digit
    // Original regex: /(?:\.0*|(\.[^0]+)0+)$/ -> captures digits after non-zero
    // New regex: /(?:\.0*|(\.[^0])0+)$/ -> only captures exactly one digit after non-zero
    assert.strictEqual(bytes.format(1024.001, { decimalPlaces: 3 }), '1.001KB');
    // The new regex would fail to remove trailing zeros in cases like 1.001
    // But the issue is that it only matches one digit after non-zero, not all
    // This causes incorrect formatting for numbers like 1.0012
    assert.strictEqual(bytes.format(1024.0012, { decimalPlaces: 4 }), '1.0012KB');
  });
});

